<?php
/** Explicitly authorized local paid acceptance; no credentials or private prompts are printed. */
require dirname(__DIR__,2).'/vendor/autoload.php';
(new think\App())->initialize();
use think\facade\Db;
use app\common\service\open_platform\OpenStore as S;
use app\common\service\open_platform\OpenKeyService as K;
use app\common\service\open_platform\OpenContracts as C;
use app\common\service\open_platform\OpenMarketBilling as B;
use app\common\service\open_platform\OpenGateway as G;
use app\common\service\open_platform\OpenVault as V;
function verify($yes,string $why): void {if(!$yes)throw new RuntimeException($why);}
$c=config('database.connections.mysql');verify(PHP_SAPI==='cli'&&$c['hostname']==='127.0.0.1'&&$c['database']==='z_cn','Local z_cn CLI only');
verify(($argv[1]??'')==='--authorized-1000','Requires explicit authorized 1000 point cap');
$user=Db::name('user')->where(['account'=>'xhadmin001','id'=>1,'tenant_id'=>1,'is_disable'=>0])->find();verify($user!==null,'Authorized local account mismatch');
request()->tenantId=1;request()->userId=1;request()->source=app\common\enum\AdminTerminalEnum::USER;
$run='local_text_'.bin2hex(random_bytes(6));$backup=[];$ids=[];$key=null;$report=['run'=>$run,'tenant_id'=>1,'user_id'=>1,'cap'=>1000,'cases'=>[]];
$evidence=dirname(__DIR__,2).'/runtime/open-platform-acceptance';if(!is_dir($evidence))mkdir($evidence,0700,true);
$lock=fopen($evidence.'/paid.lock','c');verify($lock&&flock($lock,LOCK_EX|LOCK_NB),'Another paid acceptance is running');
$priorIds=S::owner('key',1,1)->whereLike('name','local_text_%')->column('id');$priorSpent=$priorIds?(float)S::table('request')->whereIn('key_id',$priorIds)->sum('actual_user')+(float)S::table('request')->whereIn('key_id',$priorIds)->where('active',1)->sum('budget_user'):0.;verify($priorSpent<1000,'Cumulative authorized cap exhausted');$report['prior_spent']=$priorSpent;
$restore=function()use(&$backup,&$ids,&$key){if($key)S::table('key')->where('id',$key['id'])->update(['status'=>-1,'update_time'=>time()]);foreach($ids as $id)S::table('contract')->where('id',$id)->update(['status'=>'archived','update_time'=>time()]);foreach($backup as $tenant=>$row){if($row)S::table('setting')->where('tenant_id',$tenant)->update(['enabled'=>$row['enabled'],'config'=>$row['config'],'update_time'=>time()]);else S::table('setting')->where('tenant_id',$tenant)->delete();}};
try{
 foreach([0,1] as $tenant){$backup[$tenant]=S::table('setting')->where('tenant_id',$tenant)->find();$settings=S::settings($tenant);unset($settings['enabled']);$settings['models']=array_values(array_unique(array_merge($settings['models'],['2'])));$settings['rpm']=max(30,$settings['rpm']);$values=['enabled'=>1,'config'=>S::encode($settings),'update_time'=>time()];if($backup[$tenant])S::table('setting')->where('tenant_id',$tenant)->update($values);else S::table('setting')->insert($values+['tenant_id'=>$tenant,'create_time'=>time()]);}
 $key=K::create(1,1,['name'=>$run,'daily_limit'=>1000-$priorSpent,'monthly_limit'=>1000-$priorSpent,'scopes'=>['2'],'ip_allowlist'=>['127.0.0.1/32'],'expires_at'=>time()+600]);
 // Fixtures are temporarily published only behind a loopback-bound key. They are archived,
 // never promoted with fabricated verification evidence, and settings are restored in finally.
 $schema=['type'=>'object','required'=>['model','messages','max_tokens'],'properties'=>['model'=>['type'=>'string','enum'=>['qwen3.6-plus']],'messages'=>['type'=>'array','minItems'=>1,'maxItems'=>1,'items'=>['type'=>'object','required'=>['role','content'],'properties'=>['role'=>['type'=>'string','enum'=>['user']],'content'=>['type'=>'string','maxLength'=>64]]]],'max_tokens'=>['type'=>'integer','minimum'=>1,'maximum'=>16],'stream'=>['type'=>'boolean'],'stream_options'=>['type'=>'object']]];
 foreach([false,true] as $stream){$code=$run.($stream?'.stream':'.sync');$params=['model'=>'qwen3.6-plus','messages'=>[['role'=>'user','content'=>'Reply OK.']],'max_tokens'=>16,'stream'=>$stream];if($stream)$params['stream_options']=['include_usage'=>true];$values=C::validate(['code'=>$code,'method'=>'POST','path'=>'/api/v1/chat/completions','kind'=>'market','product_id'=>2,'config'=>['title'=>'Local paid acceptance','executor'=>$stream?'sse':'json','role'=>'submit','model'=>'qwen3.6-plus','when'=>['stream'=>$stream],'billable'=>true,'input'=>$schema,'example'=>$params,'responses'=>['200'=>['description'=>'Upstream protocol']],'billing'=>[['sku_id'=>2,'basis'=>'usage','max_units'=>1024,'usage_path'=>'usage.total_tokens']]]]);$ids[]=S::table('contract')->insertGetId($values+['version'=>1,'status'=>'published']+S::timestamp());}
 $call=function(array $params,string $idem)use($key){$h=curl_init('http://127.0.0.1:19874/api/v1/chat/completions');curl_setopt_array($h,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_TIMEOUT=>210,CURLOPT_POST=>true,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$key['key'],'Content-Type: application/json','Idempotency-Key: '.$idem],CURLOPT_POSTFIELDS=>S::encode($params)]);$body=curl_exec($h);$status=curl_getinfo($h,CURLINFO_HTTP_CODE);$error=curl_errno($h);curl_close($h);verify($error===0,'Local preview connection failed; do not resubmit uncertain calls');return ['status'=>$status,'body'=>$body];};
 foreach([false,true] as $stream){$spent=(float)S::table('request')->where('key_id',$key['id'])->sum('actual_user')+(float)S::table('request')->where(['key_id'=>$key['id'],'active'=>1])->sum('budget_user');$params=['model'=>'qwen3.6-plus','messages'=>[['role'=>'user','content'=>'Reply OK.']],'max_tokens'=>16,'stream'=>$stream];if($stream)$params['stream_options']=['include_usage'=>true];$op=C::match('POST','/api/v1/chat/completions',$params);$quote=B::quote(1,$op,$params);verify($priorSpent+$spent+$quote['user']<=1000,'Authorized total budget exhausted');$idem=$run.($stream?'-stream':'-sync');$wire=$call($params,$idem);$row=S::owner('request',1,1)->where(['key_id'=>$key['id'],'idempotency_hash'=>hash('sha256','POST /api/v1/chat/completions '.$idem)])->find();verify($row!==null,'Gateway rejected before tracked admission (HTTP '.$wire['status'].'): '.substr($wire['body'],0,300));
 $data=$stream?G::streamUsage($wire['body']):S::json($wire['body']);$entry=['stream'=>$stream,'http_status'=>$wire['status'],'request_id'=>$row['request_id'],'status'=>$row['status'],'billing_status'=>$row['billing_status'],'usage'=>$data['usage']??null,'charged'=>(float)$row['actual_user'],'pending_budget'=>(float)$row['budget_user'],'contract_id'=>$row['contract_id']];$report['cases'][]=$entry;file_put_contents($evidence.'/'.$run.'.json',S::encode($report));
 verify($wire['status']===200&&$row['status']==='success'&&$row['billing_status']==='settled','Real call did not finish with trusted usage: '.S::encode($entry));verify(isset($data['usage']['total_tokens']),'Trusted upstream usage missing');
 $userLogs=Db::name('user_account_log')->where(['tenant_id'=>1,'user_id'=>1])->whereLike('source_sn',$row['request_id'].'%')->select()->toArray();$tenantLogs=Db::name('tenant_point_log')->where('tenant_id',1)->whereLike('source_sn',$row['request_id'].'%')->select()->toArray();$net=function($logs){$n=0.;foreach($logs as $l)$n+=((int)$l['action']===2?1:-1)*(float)$l['change_amount'];return round($n,2);};verify($net($userLogs)===(float)$row['actual_user'],'User ledger disagrees with actual charge');verify($net($tenantLogs)===(float)$row['actual_tenant'],'Tenant ledger disagrees with cost');$replay=$call($params,$idem);verify($replay===$wire,'Idempotent response changed');verify(S::owner('request',1,1)->where(['key_id'=>$key['id'],'idempotency_hash'=>hash('sha256','POST /api/v1/chat/completions '.$idem)])->count()===1,'Replay created another request');verify(Db::name('user_account_log')->where(['tenant_id'=>1,'user_id'=>1])->whereLike('source_sn',$row['request_id'].'%')->count()===count($userLogs),'Replay charged again');$report['cases'][count($report['cases'])-1]+=['user_ledger_net'=>$net($userLogs),'tenant_ledger_net'=>$net($tenantLogs),'replay'=>'identical_no_extra_charge'];echo S::encode($report['cases'][count($report['cases'])-1]),"\n";
 }
 $report['result']='passed';
}catch(Throwable $e){$report['result']='failed';$report['failure']=$e->getMessage();}
finally{$restore();$report['charged']=(float)S::table('request')->where('key_id',$key['id']??0)->sum('actual_user');$report['pending_budget']=(float)S::table('request')->where(['key_id'=>$key['id']??0,'active'=>1])->sum('budget_user');$report['cumulative_spent']=$priorSpent+$report['charged']+$report['pending_budget'];$report['settings_restored']=true;$report['key_revoked']=true;file_put_contents($evidence.'/'.$run.'.json',S::encode($report));}
echo S::encode($report),"\n";exit($report['result']==='passed'?0:1);
